fn release_certificate(policy:&str,adapter:&AdapterConformanceCertificate,reproducibility:&ReproducibilityCertificate)->PlatformReleaseCertificate{let certificate_id="release-certificate-1".to_string();let authority_id="release-authority-1".to_string();let inventory_root_sha256=hex('8');let compatibility_contract_sha256=hex('9');let gate_root_sha256=hex('a');let artifact_attestation_sha256=hex('b');let rollout_plan_sha256=hex('c');let rollback_certificate_sha256=hex('d');let rollout_receipt_sha256=hex('e');let authority_audit_tail_hash=hex('f');let certificate_sha256=hash_serializable(&(&certificate_id,&authority_id,policy,&adapter.certificate_sha256,&reproducibility.certificate_sha256,&inventory_root_sha256,&compatibility_contract_sha256,&gate_root_sha256,&artifact_attestation_sha256,&rollout_plan_sha256,&rollback_certificate_sha256,&rollout_receipt_sha256,&authority_audit_tail_hash)).unwrap();PlatformReleaseCertificate{certificate_id,authority_id,policy_snapshot_sha256:policy.into(),adapter_conformance_sha256:adapter.certificate_sha256.clone(),reproducibility_sha256:reproducibility.certificate_sha256.clone(),inventory_root_sha256,compatibility_contract_sha256,gate_root_sha256,artifact_attestation_sha256,rollout_plan_sha256,rollback_certificate_sha256,rollout_receipt_sha256,authority_audit_tail_hash,certificate_sha256}}
fn integration_fixture()->(PlatformReleaseCertificate,PlatformIntegrationCertificate){let policy=hex('0');let adapter=adapter_certificate(&policy);let reproducibility=reproducibility_certificate(&policy);let release=release_certificate(&policy,&adapter,&reproducibility);adapter.verify().unwrap();reproducibility.verify().unwrap();release.verify().unwrap();let bundle=CrossCertificateBundle::new(&adapter,&reproducibility,&release).unwrap();let identity=PlatformIntegrationIdentity::new("integration-1","run-1","worker-1",&policy).unwrap();let scenario=IntegrationScenarioFixture::new("scenario-1",&policy,hex('1'),hex('9')).unwrap();let mut harness=IntegrationHarness::new(identity,bundle,scenario,hex('2')).unwrap();harness.start().unwrap();for step in IntegrationStep::canonical(){let evidence=if step==IntegrationStep::Finalize{hex('9')}else{hex(char::from_digit(step as u32+1,16).unwrap_or('3'))};harness.execute(step,evidence).unwrap();}let mut authority=IntegrationCertificationAuthority::new("integration-authority-1",&policy,hex('3')).unwrap();let certificate=authority.certify(&harness).unwrap();certificate.verify().unwrap();(release,certificate)}
fn operator(id:&str,role:OperatorRole)->OperatorIdentity{OperatorIdentity::new(id,role,hex('4')).unwrap()}
